// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;

// Garante que o conteúdo seja texto
const text = typeof csvRaw === "string"
  ? csvRaw
  : JSON.stringify(csvRaw);

// Divide o CSV em linhas
const lines = text
  .split(/\r?\n/)
  .map(line => line.trim())
  .filter(Boolean);

// Cabeçalhos
const headers = lines[0]
  .split(",")
  .map(header => header.trim());

// Converte cada linha em objeto
const investimentos = lines.slice(1).map(line => {
  const cols = line
    .split(",")
    .map(col => col.trim());

  const obj = {};

  headers.forEach((header, i) => {
    obj[header] = cols[i] ?? "";
  });

  // Normaliza "minimo" para número
  const valor = String(obj.minimo ?? "");

  obj.minimo = Number(
    valor.replace(/[^\d]/g, "")
  ) || 0;

  return obj;
});

// Retorna os dados para o próximo node
return {
  json: {
    investimentos
  }
};

const clientes = $input.first().json.body.clientes;

return clientes.map(cliente => {

  const nome = cliente.nome;
  const perfil = cliente.perfil.trim().toLowerCase();

  let mensagem;

  if (perfil === "conservador") {
    mensagem = `Olá, ${nome}! Com base no seu perfil conservador, nossa recomendação prioriza investimentos em renda fixa e segurança.`;

  } else if (perfil === "moderado") {
    mensagem = `Olá, ${nome}! Com base no seu perfil moderado, nossa recomendação busca um mix equilibrado entre renda fixa e renda variável.`;

  } else if (perfil === "arrojado") {
    mensagem = `Olá, ${nome}! Com base no seu perfil arrojado, nossa recomendação dá ênfase em ações e investimentos com maior potencial de retorno.`;

  } else {
    mensagem = `Perfil não identificado.`;
  }

  return {
    json: {
      mensagem: mensagem
    }
  };
});
